(function(E){ const x = E["exam-02"] = E["exam-02"] || {units:{}}; (x.units = x.units || {})["x02-l1"] = {"id":"x02-l1","patterns":["L1-clubs","PARA-money","PARA-time"],"title":{"en":"Listening Part 1: booking a course","tr":"Listening Part 1: kursa kayıt","fa":"Listening Part 1: ثبت‌نام در دوره"},"objective":{"en":"In this lesson you will learn to complete a ten-question table while a caller books short courses: follow the table row by row, pick the price that fits the caller, and write dates, codes and names exactly.","tr":"Bu derste biri kısa kurslara kayıt olurken on soruluk bir tabloyu doldurmayı öğreneceksin: tabloyu satır satır takip edecek, arayana uyan fiyatı seçecek ve tarihleri, kodları ve isimleri aynen yazacaksın.","fa":"در این درس یاد می‌گیری وقتی یک نفر در چند دوره‌ی کوتاه ثبت‌نام می‌کند، یک جدول ده‌سؤالی را کامل کنی: جدول را ردیف به ردیف دنبال کنی، قیمتی را که به تماس‌گیرنده می‌خورد انتخاب کنی و تاریخ، کد و اسم را دقیق بنویسی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: booking a course","tr":"Listening Part 1: kursa kayıt","fa":"Listening Part 1: ثبت‌نام در دوره"},"objective":{"en":"In this lesson you will learn to complete a ten-question table while a caller books short courses: follow the table row by row, pick the price that fits the caller, and write dates, codes and names exactly.","tr":"Bu derste biri kısa kurslara kayıt olurken on soruluk bir tabloyu doldurmayı öğreneceksin: tabloyu satır satır takip edecek, arayana uyan fiyatı seçecek ve tarihleri, kodları ve isimleri aynen yazacaksın.","fa":"در این درس یاد می‌گیری وقتی یک نفر در چند دوره‌ی کوتاه ثبت‌نام می‌کند، یک جدول ده‌سؤالی را کامل کنی: جدول را ردیف به ردیف دنبال کنی، قیمتی را که به تماس‌گیرنده می‌خورد انتخاب کنی و تاریخ، کد و اسم را دقیق بنویسی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word / number","tr":"1 kelime / sayı","fa":"۱ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a college photography course","tr":"Bu sınav: bir okulda fotoğraf kursu","fa":"این آزمون: دوره‌ی عکاسی در یک آموزشگاه"},"intro":{"en":"Part 1 is an everyday call in which one person needs information. Booking a course or a class is the most frequent Part 1 situation. Learn the words on the card: the table uses short labels, and the speakers say them in other words.","tr":"Part 1, bir kişinin bilgiye ihtiyaç duyduğu günlük bir telefon konuşmasıdır. Kurs ya da derse kayıt, Part 1’de en sık çıkan durumdur. Karttaki kelimeleri öğren: tablo kısa etiketler kullanır, konuşanlar bunları başka kelimelerle söyler.","fa":"Part 1 یک تماس روزمره است که در آن یک نفر به اطلاعات نیاز دارد. ثبت‌نام در دوره یا کلاس پرتکرارترین موقعیت Part 1 است. کلمه‌های کارت را یاد بگیر: جدول برچسب‌های کوتاه دارد و گوینده‌ها آن‌ها را با کلمه‌های دیگری می‌گویند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x02-l1-ctx","exam":true,"patterns":["L1-clubs","PARA-money","PARA-time"],"often":{"pattern":"L1-clubs","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Booking a one-day course","tr":"Bir günlük kursa kayıt","fa":"ثبت‌نام در یک دوره‌ی یک‌روزه"},"asks":{"en":"A caller phones a college to book short courses. One table lists three courses: the date, what you learn, the cost and other details such as the room, the tutor and what to bring.","tr":"Biri kısa kurslara kayıt olmak için bir okulu arıyor. Tek bir tablo üç kursu sıralıyor: tarih, ne öğrenileceği, ücret ve salon, eğitmen, yanına alınacaklar gibi diğer ayrıntılar.","fa":"یک نفر به یک آموزشگاه زنگ می‌زند تا در چند دوره‌ی کوتاه ثبت‌نام کند. یک جدول سه دوره را نشان می‌دهد: تاریخ، چیزی که یاد می‌گیری، هزینه و جزئیات دیگر مثل کلاس، مربی و وسایلی که باید بیاوری."},"fields":["Course","Date","What you learn","Cost","Other information","Room","Tutor","What to bring"],"words":[{"a":"book a place","b":"put you down for / enrol","tr":"yer ayırtmak, kayıt olmak","fa":"جا رزرو کردن، ثبت‌نام"},{"a":"full","b":"no places left / fully booked","tr":"dolu","fa":"پر"},{"a":"an extra date","b":"we’ve added another session","tr":"ek tarih","fa":"تاریخ اضافه"},{"a":"fee","b":"it costs / the price is","tr":"ücret","fa":"هزینه"},{"a":"reduced rate","b":"if you live locally you pay less","tr":"indirimli ücret","fa":"نرخ تخفیفی"},{"a":"bring","b":"you’ll need / please have with you","tr":"getirmek","fa":"همراه آوردن"},{"a":"tutor","b":"the person who teaches it","tr":"eğitmen","fa":"مربی"},{"a":"room","b":"it takes place in / it’s held in","tr":"salon, derslik","fa":"کلاس، اتاق"},{"a":"upstairs","b":"on the first floor","tr":"üst katta","fa":"طبقه‌ی بالا"},{"a":"being refurbished","b":"closed for repairs / being done up","tr":"yenileniyor","fa":"در حال بازسازی"},{"a":"the same for everyone","b":"there’s no discount","tr":"herkes için aynı","fa":"برای همه یکسان"},{"a":"finishes early","b":"a shorter day","tr":"erken biter","fa":"زودتر تمام می‌شود"}],"traps":[{"en":"Two prices: \"The full fee is ninety... but students pay seventy.\" Listen for who the caller is, then write the price for that person.","tr":"İki fiyat: \"Tam ücret doksan... ama öğrenciler yetmiş öder.\" Arayanın kim olduğunu dinle, sonra o kişiye ait fiyatı yaz.","fa":"دو قیمت: «هزینه‌ی کامل نود است... اما دانشجوها هفتاد می‌دهند». گوش بده تماس‌گیرنده کیست و بعد قیمتِ مخصوص همان نفر را بنویس."},{"en":"A code with letters and numbers, then a correction: \"It’s in C3... sorry, no, C8.\" Write the corrected code exactly, letter and number together.","tr":"Harf ve rakamdan oluşan bir kod, ardından düzeltme: \"C3’te... pardon, hayır, C8.\" Düzeltilmiş kodu harfi ve rakamıyla birlikte aynen yaz.","fa":"یک کد با حرف و عدد و بعد یک اصلاح: «در C3 است... ببخشید، نه، C8». کدِ اصلاح‌شده را دقیقاً بنویس، حرف و عدد با هم."},{"en":"A date said as a word: \"the twenty-third\". In a box that says \"Saturday ___ May\", write 23.","tr":"Kelimeyle söylenen bir tarih: \"the twenty-third\". \"Saturday ___ May\" yazan bir kutuya 23 yaz.","fa":"تاریخی که با کلمه گفته می‌شود: «the twenty-third». در خانه‌ای که نوشته «Saturday ___ May» بنویس 23."}],"example":{"lines":[["Receptionist","The pottery class was in Room 3 last term."],["Caller","Is it still there?"],["Receptionist","No, it’s moved to Room 9, next to the library."]],"item":"Pottery · Room ___","answer":"9","why":{"en":"Room 3 was last term. \"It’s moved to Room 9\" is the detail now.","tr":"3 numaralı salon geçen dönemdi. \"9 numaraya taşındı\" şimdiki bilgi.","fa":"اتاق ۳ مال ترم قبل بود. «به اتاق ۹ منتقل شده» اطلاعاتِ الان است."}}},{"id":"L1-clubs","ctx":["L1-clubs"],"title":{"en":"Joining a club, class or course","tr":"Bir kulübe, derse ya da kursa katılmak","fa":"ثبت‌نام در باشگاه، کلاس یا دوره"},"asks":{"en":"Someone calls or visits to join a club, a class or a holiday course. The notes collect the course details: when, where, how much, what to bring and who to contact.","tr":"Biri bir kulübe, derse ya da tatil kursuna katılmak için arar ya da gelir. Notlar kursun ayrıntılarını toplar: ne zaman, nerede, ne kadar, ne getirmeli ve kime ulaşmalı.","fa":"کسی زنگ می‌زند یا حضوری می‌آید تا در یک باشگاه، کلاس یا دوره‌ی تعطیلات ثبت‌نام کند. یادداشت‌ها جزئیات دوره را جمع می‌کنند: کی، کجا، چقدر، چه باید آورد و با چه کسی تماس گرفت."},"fields":["Name of course / club","Day and time","Venue / meeting point","Cost per session / per term","Membership fee","What to bring","Level / experience needed","Contact name"],"words":[{"a":"fee","b":"it costs / you pay","tr":"ücret","fa":"هزینه؛ شهریه"},{"a":"per session","b":"each time you come","tr":"ders başına","fa":"برای هر جلسه"},{"a":"membership","b":"joining the club for the year","tr":"üyelik","fa":"عضویت"},{"a":"discount","b":"members pay less / it's reduced for","tr":"indirim","fa":"تخفیف"},{"a":"beginners","b":"if you've never done it before","tr":"yeni başlayanlar","fa":"مبتدی‌ها"},{"a":"equipment provided","b":"we lend you one / you don't need your own","tr":"ekipman sağlanır","fa":"تجهیزات را می‌دهند"},{"a":"bring","b":"make sure you have / you'll need","tr":"getirmek","fa":"آوردن"},{"a":"meeting point","b":"we all meet outside / we start from","tr":"buluşma noktası","fa":"محل قرار"},{"a":"term","b":"the course runs for ten weeks","tr":"dönem","fa":"ترم"},{"a":"taster session","b":"a free first class to try it","tr":"deneme dersi","fa":"جلسه‌ی آزمایشی"},{"a":"age group","b":"it's for children aged 8 to 12","tr":"yaş grubu","fa":"گروه سنی"},{"a":"deposit","b":"pay something now to keep your place","tr":"kapora","fa":"بیعانه"}],"traps":[{"en":"Two prices: the full price and a price for members, students or children. Check who the caller is before you write.","tr":"İki fiyat: tam fiyat ve üyeler, öğrenciler ya da çocuklar için bir fiyat. Yazmadan önce arayanın kim olduğuna bak.","fa":"دو قیمت: قیمت کامل و قیمتی برای اعضا، دانشجوها یا بچه‌ها. قبل از نوشتن ببین تماس‌گیرنده کیست."},{"en":"The class moves: \"it used to be on Tuesdays, but this term it’s on Thursdays\". Write where and when it is now.","tr":"Ders yer ya da gün değiştirir: \"eskiden salı günleriydi ama bu dönem perşembe\". Şimdiki yeri ve zamanı yaz.","fa":"کلاس جابه‌جا می‌شود: «قبلاً سه‌شنبه‌ها بود، ولی این ترم پنجشنبه‌هاست». جا و زمانِ فعلی را بنویس."},{"en":"Things to bring: one item is \"provided\" or \"optional\". Write only what the caller must bring.","tr":"Getirilecek şeyler: bir eşya \"sağlanır\" ya da \"isteğe bağlı\" olur. Yalnızca arayanın mutlaka getirmesi gerekeni yaz.","fa":"چیزهایی که باید آورد: یکی از وسیله‌ها را «می‌دهند» یا «اختیاری» است. فقط چیزی را بنویس که تماس‌گیرنده حتماً باید بیاورد."}],"example":{"lines":[["Secretary","Sessions are on Saturday mornings, and each one is twelve pounds."],["Caller","Is that the same for everyone?"],["Secretary","No, if you’re under eighteen it’s eight pounds."],["Caller","I’m seventeen, so that’s me."]],"item":"Cost per session: £___","answer":"8","why":{"en":"Twelve pounds is the full price. The caller is seventeen, so the under-eighteen price is the answer.","tr":"On iki pound tam fiyat. Arayan on yedi yaşında, yani cevap on sekiz yaş altı fiyatı.","fa":"دوازده پوند قیمت کامل است. تماس‌گیرنده هفده سال دارد، پس جواب قیمتِ زیر هجده سال است."}},"general":true,"patterns":["L1-clubs"],"often":{"pattern":"L1-clubs","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"One table, ten gaps, one break","tr":"Bir tablo, on boşluk, bir ara","fa":"یک جدول، ده جای خالی، یک مکث"},"body":{"en":"All ten questions are in one table. You get about 30 seconds to read Questions 1-4, then a short break to read Questions 5-10. You hear the recording once, and the answers come in question order. Write ONE WORD AND/OR A NUMBER.","tr":"On sorunun hepsi tek bir tabloda. Soru 1-4’ü okumak için yaklaşık 30 saniyen var, sonra Soru 5-10’u okumak için kısa bir ara. Kaydı bir kez duyarsın ve cevaplar soru sırasıyla gelir. ONE WORD AND/OR A NUMBER yaz.","fa":"هر ده سؤال در یک جدول‌اند. حدود ۳۰ ثانیه برای خواندن سؤال‌های ۱ تا ۴ وقت داری و بعد یک مکث کوتاه برای خواندن سؤال‌های ۵ تا ۱۰. فایل را یک بار می‌شنوی و جواب‌ها به ترتیب سؤال‌ها می‌آیند. ONE WORD AND/OR A NUMBER بنویس."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Read across the row","tr":"Satırı soldan sağa oku","fa":"ردیف را از چپ به راست بخوان"},"steps":[{"en":"Read the column headings, then the first cell of each row. The row name tells you which course is being discussed.","tr":"Sütun başlıklarını, sonra her satırın ilk hücresini oku. Satırın adı hangi kurstan söz edildiğini söyler.","fa":"عنوان ستون‌ها و بعد خانه‌ی اول هر ردیف را بخوان. اسم ردیف می‌گوید درباره‌ی کدام دوره حرف می‌زنند."},{"en":"For each gap, predict the kind of answer: a date, a price, a code, a name or an ordinary word.","tr":"Her boşluk için cevabın türünü tahmin et: tarih, fiyat, kod, isim ya da sıradan bir kelime.","fa":"برای هر جای خالی نوع جواب را حدس بزن: تاریخ، قیمت، کد، اسم یا یک کلمه‌ی معمولی."},{"en":"When you hear two prices or two rooms, wait for the one that fits this caller now.","tr":"İki fiyat ya da iki salon duyduğunda, bu arayana şu an uyanı bekle.","fa":"وقتی دو قیمت یا دو اتاق می‌شنوی، صبر کن تا آن یکی که الان به این تماس‌گیرنده می‌خورد گفته شود."},{"en":"Write dates and prices as figures, and copy a spelled name letter by letter.","tr":"Tarihleri ve fiyatları rakamla yaz, harf harf söylenen ismi de harf harf yaz.","fa":"تاریخ و قیمت را با رقم بنویس و اسمی را که هجی می‌شود حرف به حرف بنویس."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Numbers that look the same","tr":"Birbirine benzeyen sayılar","fa":"عددهایی که شبیه هم‌اند"},"body":{"en":"Part 1 is full of numbers, and most of them are not the answer: the old date, the full price, the room that has changed. A code such as D7 counts as one answer, so write it without a space. Prices go next to the printed £ sign: write the number only.","tr":"Part 1 sayılarla doludur ve çoğu cevap değildir: eski tarih, tam fiyat, değişen salon. D7 gibi bir kod tek cevap sayılır, araya boşluk koymadan yaz. Fiyat yazılı £ işaretinin yanına gelir: yalnızca sayıyı yaz.","fa":"Part 1 پر از عدد است و بیشترشان جواب نیستند: تاریخ قدیمی، قیمت کامل، اتاقی که عوض شده. کدی مثل D7 یک جواب حساب می‌شود، پس بدون فاصله بنویسش. قیمت کنار علامت چاپ‌شده‌ی £ می‌آید: فقط عدد را بنویس."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One table gap, step by step","tr":"Bir tablo boşluğu, adım adım","fa":"یک جای خالی جدول، قدم به قدم"},"instruction":"Complete the table below. Write ONE WORD AND/OR A NUMBER for each answer.","item":"Watercolour painting · Cost: £___ for students","lines":[["Receptionist","The watercolour day is seventy pounds."],["Caller","I’m a full-time student. Is there a discount?"],["Receptionist","Yes, with a student card it’s fifty-two."]],"answer":"52","walk":[{"en":"Before you listen: the row is Watercolour painting, and the gap needs a price for students.","tr":"Dinlemeden önce: satır Watercolour painting ve boşluk öğrenciler için bir fiyat istiyor.","fa":"قبل از گوش دادن: ردیف Watercolour painting است و جای خالی قیمتِ مخصوص دانشجوها را می‌خواهد."},{"en":"You hear seventy first, but that is the standard price.","tr":"Önce yetmiş duyuyorsun ama o normal fiyat.","fa":"اول هفتاد را می‌شنوی، اما آن قیمت عادی است."},{"en":"The caller is a student, so write 52. The £ sign is printed already.","tr":"Arayan öğrenci, o yüzden 52 yaz. £ işareti zaten yazılı.","fa":"تماس‌گیرنده دانشجوست، پس 52 را بنویس. علامت £ از قبل چاپ شده."}]},"quick":{"prompt":"Table: \"Room ___\". You hear: \"It was in G2, but we’ve moved it to G6 because G2 is too small.\" What do you write?","options":["G2","G6","G2 or G6"],"correct":1,"why":{"en":"G2 was the old room. \"We’ve moved it to G6\" is the room now.","tr":"G2 eski salondu. \"G6’ya taşıdık\" şimdiki salon.","fa":"G2 اتاق قبلی بود. «به G6 منتقلش کردیم» اتاقِ الان است."}},"remember":{"en":"Stay on the row, wait for the detail that fits the caller now, and write codes and dates as figures.","tr":"Satırda kal, arayana şu an uyan bilgiyi bekle, kodları ve tarihleri rakamla yaz.","fa":"روی ردیف بمان، منتظر اطلاعاتی باش که الان به تماس‌گیرنده می‌خورد و کد و تاریخ را با رقم بنویس."},"type":"explain","id":"c-x02-l1-e","course":"ielts-exams","exam":"exam-02","unit":"x02-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"Ashgrove Adult College","tr":"Ashgrove Yetişkin Eğitim Okulu","fa":"آموزشگاه بزرگسالان اشگرو"},"timed":8,"ctx":["L1-clubs"],"script":[{"who":"Receptionist","line":"Good afternoon, Ashgrove Adult College, enrolments desk. How can I help?"},{"who":"Caller","line":"Hi there. I picked up your leaflet about the one-day photography courses, and I'd like to book a place. Maybe two, actually."},{"who":"Receptionist","line":"Lovely. We've got three this term: Phone Photography, Portrait Photography and Photo Editing. Which one were you thinking of?"},{"who":"Caller","line":"Phone photography first, I think. I don't own a proper camera, just my phone."},{"who":"Receptionist","line":"That's our most popular one. It runs on a Saturday. The first date was the tenth of May, but I'm afraid that one's completely full now."},{"who":"Caller","line":"Oh, that's a shame."},{"who":"Receptionist","line":"Don't worry, we've added a second date because of the demand, Saturday the seventeenth."},{"who":"Caller","line":"The seventeenth of May. Yes, I can do that."},{"who":"Receptionist","line":"The tutor spends the morning on composition, where to put things in the frame and so on. The afternoon is mostly about using natural light, because that makes the biggest difference with a phone. You won't need a flash at all."},{"who":"Caller","line":"Sounds good. And how much is it?"},{"who":"Receptionist","line":"The full fee is fifty-five pounds. Can I ask, do you live in the borough?"},{"who":"Caller","line":"Yes, I live in Ashgrove itself."},{"who":"Receptionist","line":"Then you pay the residents' rate, which is forty-four pounds."},{"who":"Caller","line":"Forty-four. That's better than I expected. Do I need to bring anything?"},{"who":"Receptionist","line":"Your phone, fully charged, obviously. And because you'll be using it all day, please bring your charger as well. There are sockets in every room. You won't need a laptop or anything like that for this one."},{"who":"Caller","line":"OK. Now, the portrait course. What does that cover?"},{"who":"Receptionist","line":"It's about photographing people, of course. But the tutor always says the hardest part isn't the camera settings. It's how to make people feel relaxed, so they don't look stiff in the picture."},{"who":"Caller","line":"That's exactly my problem with family photos. Everyone looks so serious."},{"who":"Receptionist","line":"Well, she'll help with that. It's on Sunday the first of June, and it costs sixty pounds, the same for everyone. It takes place in... let me check the room. It's usually in A4, on the ground floor. Oh no, sorry, that's changed. A4 is being painted in June, so it's in B12 now, upstairs."},{"who":"Caller","line":"B12. And who teaches it?"},{"who":"Receptionist","line":"Gwen Aldersey. She works as a wedding photographer at weekends, so she's very good with nervous people."},{"who":"Caller","line":"Could you spell her surname for me?"},{"who":"Receptionist","line":"Of course. It's A-L-D-E-R-S-E-Y."},{"who":"Caller","line":"Thanks. And what about the editing course?"},{"who":"Receptionist","line":"That one's on Saturday the seventh of June. You learn how to crop and brighten your pictures, and also how to resize a photo, so that the file is small enough to send by email without losing quality."},{"who":"Caller","line":"That would be really useful. How much is that one?"},{"who":"Receptionist","line":"It's thirty-five pounds. It's cheaper because it's a shorter day: it finishes at three."},{"who":"Caller","line":"And I suppose you have computers there?"},{"who":"Receptionist","line":"We used to. Last year everyone worked in the computer lab, but the lab's being refurbished this summer, so you'll need to bring your own laptop, I'm afraid."},{"who":"Caller","line":"Right. I can borrow my sister's."},{"who":"Receptionist","line":"Shall I put you down for the phone course and the editing course, then?"},{"who":"Caller","line":"Yes, please. I might do the portraits later in the year."},{"who":"Receptionist","line":"Lovely. You can pay online with the link I'll email you. Can I take your name?"},{"who":"Caller","line":"It's Tom Brennan. Thanks very much."}],"table":{"title":"Ashgrove Adult College: one-day photography courses","headers":["Course","Date","What you learn","Cost","Other information"],"rows":[["Phone Photography","Saturday (1) ___ May","composition; using natural (2) ___","(3) £___ (residents’ rate)","bring your phone and its (4) ___"],["Portrait Photography","Sunday 1 June","how to make people feel (5) ___","£60","room (6) ___; tutor: Gwen (7) ___"],["Photo Editing","Saturday 7 June","how to crop, brighten and (8) ___ photos","£(9) ___","bring your own (10) ___"]]},"groups":[{"instruction":"Questions 1-10. Complete the table below. Write ONE WORD AND/OR A NUMBER for each answer.","qtype":"table","questions":[{"n":1,"kind":"gap","prompt":"Phone Photography · Date: Saturday ___ May","accept":["17","17th"],"limit":1,"evidence":"Saturday the seventeenth","why":{"en":"The tenth is full. The new date is \"Saturday the seventeenth\": write 17.","tr":"Ayın onu dolu. Yeni tarih \"Saturday the seventeenth\": 17 yaz.","fa":"دهم پر است. تاریخ جدید «Saturday the seventeenth» است: بنویس 17."},"trap":["TR-selfcorrect","TR-number"]},{"n":2,"kind":"gap","prompt":"Phone Photography · What you learn: composition; using natural ___","accept":["light"],"limit":1,"evidence":"mostly about using natural light","why":{"en":"\"The afternoon is mostly about using natural light.\" A flash is not needed.","tr":"\"Öğleden sonra çoğunlukla doğal ışığı kullanmakla ilgili.\" Flaş gerekmiyor.","fa":"«بعدازظهر بیشتر درباره‌ی استفاده از نور طبیعی است». فلاش لازم نیست."},"trap":["TR-paraphrase"]},{"n":3,"kind":"gap","prompt":"Phone Photography · Cost: £___ (residents’ rate)","accept":["44"],"limit":1,"evidence":"which is forty-four pounds","why":{"en":"£55 is the full fee. He lives in the borough, so he pays the residents’ rate: 44.","tr":"55 £ tam ücret. Bölgede yaşıyor, o yüzden bölge sakini ücretini öder: 44.","fa":"۵۵ پوند هزینه‌ی کامل است. او ساکن همان منطقه است، پس نرخ ساکنان را می‌دهد: ۴۴."},"trap":["TR-price"]},{"n":4,"kind":"gap","prompt":"Phone Photography · Other information: bring your phone and its ___","accept":["charger"],"limit":1,"evidence":"please bring your charger as well","why":{"en":"\"Please bring your charger as well.\" A laptop is mentioned, but it is not needed.","tr":"\"Lütfen şarj aletini de getir.\" Dizüstü bilgisayardan söz ediliyor ama gerekmiyor.","fa":"«لطفاً شارژرت را هم بیاور». از لپ‌تاپ حرف زده می‌شود، اما لازم نیست."},"trap":["TR-paraphrase"]},{"n":5,"kind":"gap","prompt":"Portrait Photography · What you learn: how to make people feel ___","accept":["relaxed"],"limit":1,"evidence":"how to make people feel relaxed","why":{"en":"The camera settings are \"not the hardest part\". It is \"how to make people feel relaxed\".","tr":"Kamera ayarları \"en zor kısım değil\". Asıl mesele \"insanları rahatlatmak\".","fa":"تنظیمات دوربین «سخت‌ترین بخش نیست». موضوع این است که «آدم‌ها احساس آرامش کنند»."},"trap":["TR-paraphrase"]},{"n":6,"kind":"gap","prompt":"Portrait Photography · Other information: room ___","accept":["B12"],"limit":1,"evidence":"so it's in B12 now","why":{"en":"A4 is the usual room, but it is being painted: \"it’s in B12 now\". Write the code without a space.","tr":"A4 her zamanki salon ama boyanıyor: \"artık B12’de\". Kodu boşluksuz yaz.","fa":"A4 کلاس همیشگی است، اما در حال رنگ‌آمیزی است: «الان در B12 است». کد را بدون فاصله بنویس."},"trap":["TR-selfcorrect","TR-number"]},{"n":7,"kind":"gap","prompt":"Portrait Photography · Other information: tutor: Gwen ___","accept":["Aldersey"],"limit":1,"evidence":"A-L-D-E-R-S-E-Y","why":{"en":"Spelled A-L-D-E-R-S-E-Y. Check the E before the R and the E before the Y.","tr":"A-L-D-E-R-S-E-Y diye harf harf söyleniyor. R’den önceki E’yi ve Y’den önceki E’yi kontrol et.","fa":"حرف به حرف: A-L-D-E-R-S-E-Y. E قبل از R و E قبل از Y را چک کن."},"trap":["TR-spell"]},{"n":8,"kind":"gap","prompt":"Photo Editing · What you learn: how to crop, brighten and ___ photos","accept":["resize"],"limit":1,"evidence":"how to resize a photo","why":{"en":"\"Crop and brighten\" are printed. The third skill is \"how to resize a photo\".","tr":"\"Crop and brighten\" yazılı. Üçüncü beceri \"bir fotoğrafı yeniden boyutlandırmak\".","fa":"«crop and brighten» چاپ شده. مهارت سوم «تغییر اندازه‌ی عکس» است."},"trap":["TR-paraphrase"]},{"n":9,"kind":"gap","prompt":"Photo Editing · Cost: £___","accept":["35"],"limit":1,"evidence":"It's thirty-five pounds","why":{"en":"\"It’s thirty-five pounds\", cheaper because it is a shorter day.","tr":"\"Otuz beş pound\", daha kısa bir gün olduğu için daha ucuz.","fa":"«سی‌وپنج پوند است»، ارزان‌تر چون روزش کوتاه‌تر است."},"trap":["TR-number"]},{"n":10,"kind":"gap","prompt":"Photo Editing · Other information: bring your own ___","accept":["laptop"],"limit":1,"evidence":"bring your own laptop","why":{"en":"The computer lab was used last year. This summer \"you’ll need to bring your own laptop\".","tr":"Bilgisayar laboratuvarı geçen yıl kullanılıyordu. Bu yaz \"kendi dizüstü bilgisayarını getirmen gerekecek\".","fa":"پارسال از سایت کامپیوتر استفاده می‌شد. امسال تابستان «باید لپ‌تاپ خودت را بیاوری»."},"trap":["TR-selfcorrect"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Receptionist":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_lily"},"role":"College receptionist"},"Caller":{"accent":"North American","gender":"M","tts":{"engine":"kokoro","voice":"am_michael"},"role":"Caller who wants a course"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear a telephone conversation between a receptionist at an adult college and a man who wants to book a photography course. First, you have some time to look at Questions 1 to 4."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-4"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 4."},{"type":"lines","from":0,"to":14,"note":"phone line: light telephone filter on both voices; a short ring before line 0"},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 5 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 5-10"},{"type":"announcer","text":"Now listen and answer Questions 5 to 10."},{"type":"lines","from":15,"to":33},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x02-l1-d","course":"ielts-exams","exam":"exam-02","unit":"x02-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"If a course is \"fully booked\", it...","options":["has no places left","is cheaper than usual","has an extra tutor"],"correct":0,"why":{"en":"Fully booked = every place has been taken.","tr":"Fully booked = bütün yerler dolu.","fa":"fully booked یعنی همه‌ی جاها پر شده."}},{"tests":"paraphrase","point":1,"prompt":"The table says \"Cost: £___ (residents’ rate)\". Which words in a recording lead to this price?","options":["the full fee is...","it’s the same for everyone...","if you live in the area, it’s..."],"correct":2,"why":{"en":"A residents’ rate is for people who live locally: \"if you live in the area\".","tr":"Residents’ rate bölgede yaşayanlar içindir: \"if you live in the area\".","fa":"residents’ rate مخصوص کسانی است که در همان محل زندگی می‌کنند: «if you live in the area»."}},{"tests":"method","point":2,"prompt":"Before the recording starts, you see the gap \"Saturday ___ May\". What kind of answer do you expect?","options":["a day of the week","a number for the date","the name of a month"],"correct":1,"why":{"en":"Saturday and May are printed, so the gap needs the number of the day.","tr":"Saturday ve May yazılı; boşluk günün sayısını istiyor.","fa":"Saturday و May چاپ شده‌اند، پس جای خالی عددِ روز را می‌خواهد."}},{"tests":"trap","point":3,"prompt":"Gap: \"Room ___\". You hear: \"It’s on the list as F1, but that’s the old room. We’re in F5 now.\" What do you write?","options":["F5","F1","F1 or F5"],"correct":0,"why":{"en":"F1 is the old room on the list. \"We’re in F5 now.\"","tr":"F1 listedeki eski salon. \"Artık F5’teyiz.\"","fa":"F1 اتاق قدیمیِ فهرست است. «الان در F5 هستیم»."}},{"tests":"trap","point":3,"prompt":"Gap: \"£___\". You hear: \"It’s twenty-eight pounds for adults and fourteen for children.\" The caller is booking for herself. What do you write?","options":["14","42","28"],"correct":2,"why":{"en":"She is an adult, so the adult price applies: 28.","tr":"Kendisi yetişkin, o yüzden yetişkin fiyatı geçerli: 28.","fa":"خودش بزرگسال است، پس قیمت بزرگسال حساب می‌شود: ۲۸."}}],"id":"c-x02-l1-x","course":"ielts-exams","exam":"exam-02","unit":"x02-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
